/* Private, persistent answers. Refresh only on request or a return after five minutes. */
let questionsLoadedAt=0;
const drafts=new Map();
function questionNode(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
function rememberQuestionDrafts(){for(const form of document.querySelectorAll('.question-form'))drafts.set(form.dataset.id,{version:Number(form.dataset.version),text:form.querySelector('textarea').value,choice:form.querySelector('input:checked')?.value||''});}
function renderQuestions(data){if(data.schemaVersion!==1||!Array.isArray(data.questions))throw Error('Unsupported questions');rememberQuestionDrafts();const root=document.getElementById('question-list');root.replaceChildren();const pending=data.questions.filter(q=>q.status==='open'&&!q.saved).length;document.getElementById('question-count').textContent=pending?pending+' awaiting your answer':'No questions waiting';
 if(!data.questions.length){root.append(questionNode('p','Development questions will appear here when I need your input.','muted'));return;}
 const history=questionNode('details',undefined,'question-history');history.append(questionNode('summary','Answered and resolved questions'));let historical=0;
 for(const q of data.questions){if(q.status==='resolved'){const item=questionNode('article',undefined,'question-card');item.append(questionNode('h3',q.title),questionNode('p',q.context,'muted'),questionNode('p',q.saved?.answer||'Resolved during development.','saved-answer'));history.append(item);historical++;continue;}
 const form=questionNode('form',undefined,'question-form question-card');form.dataset.id=q.id;form.dataset.version=q.version;const fieldset=questionNode('fieldset');fieldset.append(questionNode('legend',q.title));if(q.context)fieldset.append(questionNode('p',q.context,'muted'));const draft=drafts.get(q.id),saved=q.saved?.answer||'';const sameDraft=draft?.version===q.version;const choice=sameDraft?draft.choice:q.options.includes(saved)?saved:'';
 for(const [index,option] of q.options.entries()){const label=questionNode('label',undefined,'question-option'),radio=questionNode('input');radio.type='radio';radio.name='choice';radio.value=option;radio.id='question-'+q.id+'-'+index;radio.checked=choice===option;label.append(radio,questionNode('span',option));fieldset.append(label);}
 const label=questionNode('label','Your answer or additional details','answer-label'),text=questionNode('textarea');text.id='answer-'+q.id;text.rows=3;text.maxLength=4000;text.name='answer';label.htmlFor=text.id;text.value=sameDraft?draft.text:q.options.includes(saved)?'':saved;fieldset.append(label,text);const footer=questionNode('div',undefined,'question-footer'),button=questionNode('button',q.saved?'Update answer':'Save answer'),status=questionNode('p',q.saved?'Saved '+new Date(q.saved.updated_at).toLocaleString():'','timestamp');button.type='submit';status.setAttribute('role','status');status.setAttribute('aria-live','polite');footer.append(button,status);form.append(fieldset,footer);
 form.addEventListener('submit',async event=>{event.preventDefault();const selected=form.querySelector('input:checked')?.value||'',details=text.value.trim(),answer=selected&&details?selected+'\n'+details:details||selected;if(!answer){status.textContent='Choose an option or type an answer.';text.focus();return;}if(answer.length>4000){status.textContent='Please shorten your answer to 4000 characters.';return;}button.disabled=true;status.textContent='Saving answer…';try{const response=await fetch('/api/answers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({questionId:q.id,version:q.version,answer})});const result=await response.json();if(!response.ok)throw Error(result.error||'Answer was not saved.');status.textContent='Saved '+new Date(result.updatedAt).toLocaleString()+'. I can read this during development.';button.textContent='Update answer';form.classList.add('answered');drafts.set(q.id,{version:q.version,text:text.value,choice:selected});q.saved={answer:result.answer,updated_at:result.updatedAt};const left=data.questions.filter(item=>item.status==='open'&&!item.saved).length;document.getElementById('question-count').textContent=left?left+' awaiting your answer':'No questions waiting';}catch(error){status.textContent=error.message+' Your draft is still here.';}finally{button.disabled=false;}});
 if(q.saved)form.classList.add('answered');root.append(form);
 }if(historical)root.append(history);
}
async function loadQuestions(){const button=document.getElementById('refresh-questions'),state=document.getElementById('question-state');button.disabled=true;state.textContent='Checking questions…';const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const response=await fetch('/api/questions',{cache:'no-store',signal:controller.signal});if(response.status===401){state.replaceChildren(questionNode('span','Sign in to answer questions. '));const link=questionNode('a','Sign in with ChatGPT');link.href='/signin-with-chatgpt?return_to=%2Fprogress.html';link.target='_top';state.append(link);return;}const result=await response.json();if(!response.ok)throw Error(result.error||'Questions unavailable.');renderQuestions(result);questionsLoadedAt=Date.now();state.textContent='Answers are saved privately and read during development.';}catch(error){state.textContent='Questions could not be reached. Your drafts are preserved; try Refresh questions.';}finally{clearTimeout(timeout);button.disabled=false;}}
document.getElementById('refresh-questions').addEventListener('click',loadQuestions);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()-questionsLoadedAt>300000)loadQuestions();});
loadQuestions();
